/**
 * CURATOR-126
 * Shutdown the Curator client while there are still background operations running.
 */
@Test
public void testShutdown() throws Exception {
    Timing timing = new Timing();
    CuratorFramework client = CuratorFrameworkFactory.builder().connectString(server.getConnectString()).sessionTimeoutMs(timing.session()).connectionTimeoutMs(timing.connection()).retryPolicy(new RetryOneTime(1)).maxCloseWaitMs(timing.forWaiting().milliseconds()).build();
    try {
        final AtomicBoolean hadIllegalStateException = new AtomicBoolean(false);
        ((CuratorFrameworkImpl) client).debugUnhandledErrorListener = new UnhandledErrorListener() {

            @Override
            public void unhandledError(String message, Throwable e) {
                if (e instanceof IllegalStateException) {
                    hadIllegalStateException.set(true);
                }
            }
        };
        client.start();
        final CountDownLatch operationReadyLatch = new CountDownLatch(1);
        ((CuratorFrameworkImpl) client).debugListener = new CuratorFrameworkImpl.DebugBackgroundListener() {

            @Override
            public void listen(OperationAndData<?> data) {
                try {
                    operationReadyLatch.await();
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        };
        // queue a background operation that will block due to the debugListener
        client.create().inBackground().forPath("/hey");
        timing.sleepABit();
        // close the client while the background is still blocked
        client.close();
        // unblock the background
        operationReadyLatch.countDown();
        timing.sleepABit();
        // should not generate an exception
        Assert.assertFalse(hadIllegalStateException.get());
    } finally {
        CloseableUtils.closeQuietly(client);
    }
}

@Test(description = "test case for CURATOR-525")
public void testValidateConnectionEventRaces() throws Exception {
    // test for CURATOR-525 - there is a race whereby Curator can go to LOST
    // after the connection has been repaired. Prior to the fix, the Curator
    // instance would become a zombie, never leaving the LOST state
    try (CuratorFramework client = CuratorFrameworkFactory.newClient(server.getConnectString(), 2000, 1000, new RetryOneTime(1))) {
        CuratorFrameworkImpl clientImpl = (CuratorFrameworkImpl) client;
        client.start();
        client.getChildren().forPath("/");
        client.create().forPath("/foo");
        BlockingQueue<ConnectionState> stateQueue = new LinkedBlockingQueue<>();
        client.getConnectionStateListenable().addListener((__, newState) -> stateQueue.add(newState));
        server.stop();
        Assert.assertEquals(timing.takeFromQueue(stateQueue), ConnectionState.SUSPENDED);
        Assert.assertEquals(timing.takeFromQueue(stateQueue), ConnectionState.LOST);
        clientImpl.debugCheckBackgroundRetryReadyLatch = new CountDownLatch(1);
        clientImpl.debugCheckBackgroundRetryLatch = new CountDownLatch(1);
        client.delete().guaranteed().inBackground().forPath("/foo");
        timing.awaitLatch(clientImpl.debugCheckBackgroundRetryReadyLatch);
        server.restart();
        Assert.assertEquals(timing.takeFromQueue(stateQueue), ConnectionState.RECONNECTED);
        // simulate an expiration being handled after the connection is repaired
        clientImpl.injectedCode = KeeperException.Code.SESSIONEXPIRED;
        clientImpl.debugCheckBackgroundRetryLatch.countDown();
        Assert.assertEquals(timing.takeFromQueue(stateQueue), ConnectionState.LOST);
        Assert.assertEquals(timing.takeFromQueue(stateQueue), ConnectionState.RECONNECTED);
    }
}

