        }
        Assert.assertTrue(timing.awaitLatch(reconnectedLatch));
        Assert.assertNotNull(client.checkExists().forPath("/temp"));
    } finally {
        CloseableUtils.closeQuietly(client);
        CloseableUtils.closeQuietly(cluster);
    }
