@Test
public void testLostRestart() throws Exception {
    final Timing timing = new Timing();
    CuratorFramework client = null;
    TestingCluster cluster = createAndStartCluster(3);
    try {
        client = CuratorFrameworkFactory.newClient(cluster.getConnectString(), timing.session(), timing.connection(), new RetryOneTime(1));
        client.start();
        client.sync().forPath("/");
        final AtomicReference<Exception> error = new AtomicReference<Exception>(null);
        final AtomicReference<String> lockNode = new AtomicReference<String>(null);
        final Semaphore semaphore = new Semaphore(0);
        final CountDownLatch lostLatch = new CountDownLatch(1);
        final CountDownLatch internalLostLatch = new CountDownLatch(1);
        LeaderSelectorListener listener = new LeaderSelectorListener() {

            @Override
            public void takeLeadership(CuratorFramework client) throws Exception {
                try {
                    List<String> names = client.getChildren().forPath("/leader");
                    if (names.size() != 1) {
                        semaphore.release();
                        Exception exception = new Exception("Names size isn't 1: " + names.size());
                        error.set(exception);
                        return;
                    }
                    lockNode.set(names.get(0));
                    semaphore.release();
                    if (!timing.multiple(4).awaitLatch(internalLostLatch)) {
                        error.set(new Exception("internalLostLatch await failed"));
                    }
                } finally {
                    lostLatch.countDown();
                }
            }

            @Override
            public void stateChanged(CuratorFramework client, ConnectionState newState) {
                if (newState == ConnectionState.LOST) {
                    internalLostLatch.countDown();
                }
            }
        };
        LeaderSelector selector = new LeaderSelector(client, "/leader", listener);
        selector.start();
        Assert.assertTrue(timing.multiple(4).acquireSemaphore(semaphore));
        if (error.get() != null) {
            throw new AssertionError(error.get());
        }
        Collection<InstanceSpec> instances = cluster.getInstances();
        cluster.stop();
        Assert.assertTrue(timing.multiple(4).awaitLatch(lostLatch));
        timing.sleepABit();
        Assert.assertFalse(selector.hasLeadership());
        Assert.assertNotNull(lockNode.get());
        cluster = new TestingCluster(instances.toArray(new InstanceSpec[instances.size()]));
        cluster.start();
        try {
            // simulate the lock deleting due to session expiration
            client.delete().forPath(ZKPaths.makePath("/leader", lockNode.get()));
        } catch (Exception ignore) {
            // ignore
        }
        Assert.assertTrue(semaphore.availablePermits() == 0);
        Assert.assertFalse(selector.hasLeadership());
        selector.requeue();
        Assert.assertTrue(timing.multiple(4).acquireSemaphore(semaphore));
    } finally {
        CloseableUtils.closeQuietly(client);
        CloseableUtils.closeQuietly(cluster);
    }
}

/**
 * Create a LeaderSelector but close the connection right after the "lock" znode
 * has been created.
 *
 * @throws Exception
 */
@Test
public void flappingTest() throws Exception {
    final CuratorFramework client = CuratorFrameworkFactory.builder().connectString(server.getConnectString()).retryPolicy(new RetryNTimes(1, 500)).sessionTimeoutMs(30000).build();
    final TestLeaderSelectorListener listener = new TestLeaderSelectorListener();
    LeaderSelector leaderSelector1 = new LeaderSelector(client, ChaosMonkeyCnxnFactory.CHAOS_ZNODE, listener);
    LeaderSelector leaderSelector2 = null;
    client.start();
    try {
        client.create().forPath(ChaosMonkeyCnxnFactory.CHAOS_ZNODE);
        leaderSelector1.start();
        // At this point the ChaosMonkeyZookeeperServer must close the connection
        // right after the lock znode is created.
        Assert.assertTrue(listener.reconnected.await(10, TimeUnit.SECONDS), "Connection has not been lost");
        // Check that leader ship has failed
        Assert.assertEquals(listener.takeLeadership.getCount(), 1);
        // Wait FailedDelete
        Thread.sleep(ChaosMonkeyCnxnFactory.LOCKOUT_DURATION_MS * 2);
        // Check that there is no znode
        final int children = client.getChildren().forPath(ChaosMonkeyCnxnFactory.CHAOS_ZNODE).size();
        Assert.assertEquals(children, 0, "Still " + children + " znodes under " + ChaosMonkeyCnxnFactory.CHAOS_ZNODE + " lock");
        // Check that a new LeaderSelector can be started
        leaderSelector2 = new LeaderSelector(client, ChaosMonkeyCnxnFactory.CHAOS_ZNODE, listener);
        leaderSelector2.start();
        Assert.assertTrue(listener.takeLeadership.await(1, TimeUnit.SECONDS));
    } finally {
        try {
            leaderSelector1.close();
        } catch (IllegalStateException e) {
            Assert.fail(e.getMessage());
        }
        try {
            if (leaderSelector2 != null) {
                leaderSelector2.close();
            }
        } catch (IllegalStateException e) {
            Assert.fail(e.getMessage());
        }
        client.close();
    }
}

