                        revokeLatch.countDown();
                    }
                };
                lock.makeRevocable(listener);
                lock.acquire();
                lockLatch.countDown();
                revokeLatch.await();
                lock.release();
                return null;
            }
        });
        Future<Void> f2 = executorService.submit(new Callable<Void>() {

            @Override
            public Void call() throws Exception {
